conditions.leftValue:
={{
(() => {
  const src = $('Telegram Trigger').first().json;
  const msg = src.message || src;

  const hasPhoto =
    Array.isArray(msg.photo) &&
    msg.photo.length > 0;

  const hasImageDocument =
    !!msg.document?.file_id &&
    (
      (msg.document?.mime_type || '').startsWith('image/') ||
      /\.(jpg|jpeg|png|webp)$/i.test(msg.document?.file_name || '')
    );

  return hasPhoto || hasImageDocument;
})()
}}

parameters.fileId:
={{
(() => {
  const src = $('Telegram Trigger').first().json;
  const msg = src.message || src;

  if (Array.isArray(msg.photo) && msg.photo.length > 0) {
    return msg.photo[msg.photo.length - 1].file_id;
  }

  if (
    msg.document?.file_id &&
    (
      (msg.document?.mime_type || '').startsWith('image/') ||
      /\.(jpg|jpeg|png|webp)$/i.test(msg.document?.file_name || '')
    )
  ) {
    return msg.document.file_id;
  }

  return '';
})()
}}

