value.reference:
={{
  (() => {
    const text = $('Telegram Trigger').item.json.message?.text || '';
    const payload = text.split(' ')[1] || '';

    if (!text.startsWith('/start')) return '';
    if (!payload.startsWith('ref_')) return '';

    return payload.replace('ref_', '');
  })()
}}

value.language:
={{ (() => {
  const rawCode =
    $('Telegram Trigger').item.json.message?.from?.language_code ?? '';

  const code = String(rawCode)
    .toLowerCase()
    .replace('_', '-')
    .split('-')[0];

  return ['ru', 'en', 'es', 'uz', 'ar'].includes(code)
    ? code
    : 'ru';
})() }}

